    "0x prefix (0x48 0x65)": ["0x उपसर्ग (0x48 0x65)", "Prefijo 0x (0x48 0x65)", "Préfixe 0x (0x48 0x65)", "0x-Präfix (0x48 0x65)", "0x接頭辞（0x48 0x65）", "0x 前缀（0x48 0x65）", "بادئة 0x (0x48 0x65)"],
    "\\x prefix (\\x48\\x65)": ["\\x उपसर्ग (\\x48\\x65)", "Prefijo \\x (\\x48\\x65)", "Préfixe \\x (\\x48\\x65)", "\\x-Präfix (\\x48\\x65)", "\\x接頭辞（\\x48\\x65）", "\\x 前缀（\\x48\\x65）", "بادئة \\x (\\x48\\x65)"],
